import java.text.DecimalFormat;
import java.util.Scanner;
public class JAverageEvenNums {
	public static void main(String[] args) {
		//Khatwa 1: Tarif al-mutaghayyirat allati nahtajuha li-hadha al-barnamaj
		int total = 0;
		int count = 0;
		double average;
		//Khatwa 2: Iqra' al-awwal adad sahih alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil raqm sahih (0 li-l-inha): ");
		int num = scan.nextInt();
		//Khatwa 3: Aamil al-adad alladhi adkhalahu al-mustakhdim, thumma istaqbil wa aamil al-aadad al-taliya ma dam al-mustakhdim yadkhul adad ghayr sifri; w'illa tawqaf
		while (num != 0) {
			if (num % 2 == 0) {
				count++;
				total += num;
			}
			System.out.println("Majmu' al-a3dad al-zawjiya ila al-aan huwa " + total+", , adad al-a3dad al-zawjiya = "+count);
			System.out.println("Adkhil raqm sahih (0 li-l-inha): ");
			num = scan.nextInt();   
		}
		scan.close();
		//Khatwa 4: Ihsib wa atba' al-mutawassit li-al-a3dad al-zawjiya allati adkhalaha al-mustakhdim
		if (count == 0) {
			System.out.println("Lam yudkhal ay a3dad zawjiya.");
		} else {
			average = (double) total / count;
			DecimalFormat fmt = new DecimalFormat("0.###");
			System.out.println("Al-mutawassit huwa " + fmt.format(average));
		}
	}
}
